import numpy as np, glob, os
from datetime import datetime
from scipy.signal import butter, filtfilt

def bandpass(x, fs, low, high, order=3):
    nyq=0.5*fs
    low=max(0.1, low)
    high=min(high, nyq*0.95)
    if low>=high:
        return x
    b,a=butter(order,[low/nyq,high/nyq],btype='band')
    return filtfilt(b,a,x,axis=0)

def moving_avg(x, n):
    if n<=1:
        return x
    return np.convolve(x, np.ones(n)/n, mode='same')


def parse_channels(ch, nchan, data):
    names=None
    if ch is not None:
        if isinstance(ch, np.ndarray) and ch.shape==():
            ch=ch.item()
        if isinstance(ch, bytes):
            ch=ch.decode()
        if isinstance(ch, np.ndarray):
            ch=str(ch)
        if isinstance(ch, str) and ',' in ch:
            names=[c.strip() for c in ch.split(',')]
        elif isinstance(ch, str):
            names=[ch.strip()]
    var=data.var(axis=0)
    z_idx=None
    h_idx=[]
    if names and len(names)==nchan:
        for i,n in enumerate(names):
            up=n.upper()
            if 'Z' in up:
                z_idx=i
            elif any(k in up for k in ['N','E','1','2']):
                h_idx.append(i)
            else:
                h_idx.append(i)
        if z_idx is None:
            z_idx=int(np.argmax(var))
        if not h_idx:
            h_idx=[i for i in range(nchan) if i!=z_idx]
    else:
        z_idx=int(np.argmax(var))
        h_idx=[i for i in range(nchan) if i!=z_idx]
    return z_idx, h_idx

files=glob.glob('/root/data/*.npz')
for fn in files[:5]:
    with np.load(fn, allow_pickle=True) as f:
        data=f['data'].astype(float)
        dt=float(f['dt'])
        dist=float(f['distance_km'])
        event_time=str(f['event_time'])
        start_time=str(f['start_time'])
        ch=f['channels']
    t_event=datetime.strptime(event_time,'%Y-%m-%dT%H:%M:%S.%f')
    t_start=datetime.strptime(start_time,'%Y-%m-%dT%H:%M:%S.%f')
    offset=(t_event-t_start).total_seconds()
    fs=1/dt
    data=data-np.mean(data,axis=0,keepdims=True)
    z_idx,h_idx=parse_channels(ch, data.shape[1], data)
    data_f=bandpass(data,fs,1.0,20.0)
    sig=data_f[:,z_idx]
    env=moving_avg(np.abs(sig), int(0.2*fs))
    grad=np.gradient(env)
    p_pred=int((offset+dist/5.0)*fs)
    win=int(6*fs)
    start=max(0,p_pred-win)
    end=min(len(sig), p_pred+win)
    idx=start+int(np.argmax(grad[start:end]))
    print(os.path.basename(fn),'pred',p_pred,'grad',idx,'z_idx',z_idx)
